#!/usr/bin/env bash
# Re-vendors the marketplace packs ex4pm consumes and rewrites PACKS.lock.json
# and provenance.ttl deterministically (no timestamps): same pack bytes + same
# source git sha => byte-identical lock. Run from anywhere:
#
#   priv/ggen/vendor/sync.sh [path-to-ggen-marketplace]   # default ~/ggen-marketplace
#
# Then run: mix ex4pm.ggen.sync && mix ex4pm.ggen.verify_determinism --all
# `mix ex4pm.ggen.verify_determinism` refuses when a vendored file's sha256
# differs from PACKS.lock.json.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
market="${1:-$HOME/ggen-marketplace}"
packs=(ex4pm-wasm4pm-bindings-pack standing-ladder-pack)

[ -d "$market/packs" ] || { echo "sync.sh: no packs dir at $market" >&2; exit 2; }

for p in "${packs[@]}"; do
  src="$market/packs/$p"
  [ -f "$src/ontology.ttl" ] || { echo "sync.sh: missing $src/ontology.ttl" >&2; exit 2; }
  cp "$src/ontology.ttl" "$here/$p.ontology.ttl"
  rm -rf "$here/gates/$p"
  mkdir -p "$here/gates/$p"
  if [ -d "$src/gates" ]; then
    for g in "$src"/gates/*.rq; do cp "$g" "$here/gates/$p/"; done
  fi
done

python3 - "$here" "$market" "${packs[@]}" <<'PY'
import hashlib, json, os, re, subprocess, sys

here, market, *packs = sys.argv[1:]

def sha256(path):
    return hashlib.sha256(open(path, "rb").read()).hexdigest()

def git(*args):
    return subprocess.check_output(["git", "-C", market, *args], text=True).strip()

head = git("rev-parse", "HEAD")
lock = {"schema": "ex4pm.ggen.vendor-lock/v1", "source_repo": "ggen-marketplace",
        "source_git_sha": head, "packs": []}
ttl = ["# GENERATED by priv/ggen/vendor/sync.sh from PACKS.lock.json. Do not edit.",
       "@prefix ex4pmal: <https://chatman.ai/ex4pm/algorithm-registry#> .",
       "@prefix prov: <http://www.w3.org/ns/prov#> .",
       "@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .", ""]

for p in packs:
    toml = open(os.path.join(market, "packs", p, "pack.toml")).read()
    version = re.search(r'^version\s*=\s*"([^"]+)"', toml, re.M).group(1)
    dirty = git("status", "--porcelain", "--", f"packs/{p}") != ""
    files = []
    entries = [(f"{p}.ontology.ttl", f"packs/{p}/ontology.ttl")]
    gdir = os.path.join(here, "gates", p)
    for g in sorted(os.listdir(gdir)):
        entries.append((f"gates/{p}/{g}", f"packs/{p}/gates/{g}"))
    for rel, srcrel in entries:
        files.append({"path": rel, "source_path": srcrel,
                      "sha256": sha256(os.path.join(here, rel))})
    lock["packs"].append({"name": p, "version": version,
                          "source_tree_dirty": dirty, "files": files})
    onto = files[0]["sha256"]
    iri = "ex4pmal:pack_" + p.replace("-", "_")
    ttl += [f"{iri} a prov:Entity ;",
            f'    ex4pmal:packName "{p}" ;',
            f'    ex4pmal:packVersion "{version}" ;',
            f'    ex4pmal:packOntologySha256 "{onto}" ;',
            f'    ex4pmal:sourceGitSha "{head}" ;',
            f'    ex4pmal:sourceTreeDirty "{str(dirty).lower()}"^^xsd:boolean .', ""]

with open(os.path.join(here, "provenance.ttl"), "w") as f:
    f.write("\n".join(ttl))
lock["generated"] = [{"path": "provenance.ttl", "sha256": sha256(os.path.join(here, "provenance.ttl"))}]
with open(os.path.join(here, "PACKS.lock.json"), "w") as f:
    json.dump(lock, f, indent=2)
    f.write("\n")
PY
echo "sync.sh: vendored ${packs[*]} from $market"
